function pinKnownSourceFields(plan,n){
 const entry=NORMALIZED_CORPUS[n];must(entry&&plan.cuts.length===n,'known normalized corpus size required');
 for(const pin of entry.pins){const cut=plan.cuts[pin.cutIndex];must(cut?.layout===pin.layout,'known source field layout changed');
  if(pin.field==='stagger'){must(Number.isFinite(cut.stagger),'known stagger must stay finite');cut.stagger=pin.value;continue;}
  const target=pin.field==='params.cats'?cut.params.cats:cut.treatP;must(target&&typeof target==='object','known source container required');
  if(pin.field==='params.cats'){must(Array.isArray(target)&&target.length===pin.value.length,'known category array shape changed');for(let i=0;i<pin.value.length;i++)target[i]=pin.value[i];must(target===cut.params.cats,'category alias changed');}
  else{must([Object.prototype,null].includes(Object.getPrototypeOf(target)),'known treatment plain container required');for(const key of pin.knownOwnKeys){const descriptor=Object.getOwnPropertyDescriptor(target,key);must(!descriptor||Object.hasOwn(descriptor,'value')&&descriptor.configurable&&descriptor.writable&&descriptor.enumerable,'known treatment descriptor changed');if(descriptor)delete target[key];}for(const [key,value]of Object.entries(pin.value))Object.defineProperty(target,key,{value,writable:true,enumerable:true,configurable:true});must(target===cut.treatP,'treatment alias changed');}
 }
}

